#include "rendering/SplashScreen.h"

#include <SDL3/SDL.h>
#include <SDL3_image/SDL_image.h>
#include <algorithm>
#include <cstddef>

// Generated by CMake from .engine/system/splash.png.
extern const unsigned char kPocketSplashPng[];
extern const std::size_t kPocketSplashPngSize;

namespace SplashScreen {

bool Show(SDL_Renderer *renderer, float seconds) {
    if (renderer == nullptr || seconds <= 0.0f) return true;
    SDL_IOStream *stream = SDL_IOFromConstMem(kPocketSplashPng, kPocketSplashPngSize);
    SDL_Texture *logo = stream != nullptr ? IMG_LoadTexture_IO(renderer, stream, true) : nullptr;
    if (logo == nullptr) {
        SDL_LogWarn(SDL_LOG_CATEGORY_APPLICATION, "splash screen image could not be loaded: %s", SDL_GetError());
        return true;
    }
    SDL_SetTextureScaleMode(logo, SDL_SCALEMODE_LINEAR);
    float logo_w = 0.0f, logo_h = 0.0f;
    SDL_GetTextureSize(logo, &logo_w, &logo_h);

    const float fade = std::min(0.5f, seconds * 0.25f);
    const Uint64 start = SDL_GetTicksNS();
    bool open = true;
    for (;;) {
        SDL_Event event;
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_EVENT_QUIT || event.type == SDL_EVENT_WINDOW_CLOSE_REQUESTED) open = false;
        }
        const float t = static_cast<float>(SDL_GetTicksNS() - start) / 1e9f;
        if (!open || t >= seconds) break;
        const float alpha = std::clamp(std::min(t / fade, (seconds - t) / fade), 0.0f, 1.0f);

        // Centered at up to 60% of the width and 30% of the height of the output.
        int out_w = 0, out_h = 0;
        SDL_GetCurrentRenderOutputSize(renderer, &out_w, &out_h);
        const float scale = std::min(out_w * 0.6f / logo_w, out_h * 0.3f / logo_h);
        const SDL_FRect dst{(out_w - logo_w * scale) * 0.5f, (out_h - logo_h * scale) * 0.5f, logo_w * scale,
                            logo_h * scale};
        SDL_SetRenderViewport(renderer, nullptr);
        SDL_SetRenderDrawColor(renderer, 17, 19, 27, 255);
        SDL_RenderClear(renderer);
        SDL_SetTextureAlphaModFloat(logo, alpha);
        SDL_RenderTexture(renderer, logo, nullptr, &dst);
        SDL_RenderPresent(renderer);
        SDL_Delay(8);
    }
    SDL_DestroyTexture(logo);
    return open;
}

}  // namespace SplashScreen
